<?php require 'config.php'; $u=require_login(); if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: dashboard.php');exit;}check_csrf();$code=strtoupper(trim($_POST['code']??''));$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM keys WHERE code=? AND used_by IS NULL');$s->execute([$code]);$k=$s->fetch();if(!$k){$pdo->rollBack();flash('Ключ не найден или уже использован.');header('Location: dashboard.php');exit;}$days=(int)$k['days'];$expires=$days===0?0:time()+$days*86400;$plan=$days===0?'forever':plan_name($days);$s=$pdo->prepare('UPDATE users SET plan=?,plan_expires=? WHERE id=?');$s->execute([$plan,$expires,$u['id']]);$s=$pdo->prepare('UPDATE keys SET used_by=?,used_at=? WHERE id=?');$s->execute([$u['id'],time(),$k['id']]);$pdo->commit();flash('Ключ активирован: '.$plan);header('Location: dashboard.php');
